/bin/zsh -lc "cat > bin/wordfreq.js <<'EOF'
#"'!/usr/bin/env node

import { readFileSync } from '"'node:fs';

const usage = 'Usage: wordfreq [-n <count>] [--ignore-case] [--min-length <k>] <file...>';

try {
  const args = process.argv.slice(2);
  const files = [];
  let count = 10;
  let minLength = 1;
  let ignoreCase = false;
  let positional = false;
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (positional) files.push(arg);
    else if (arg === '--') positional = true;
    else if (arg === '--help' || arg === '-h') {
      console.log(usage);
      process.exit(0);
    } else if (arg === '--ignore-case') ignoreCase = true;
    else if (arg === '-n' || arg === '--min-length') {
      const value = args[++i];
      if ("'!/''^'"\\d+"'$/.test(value ?? '"'') || "'!Number.isSafeInteger(Number(value))) {
        throw new Error(`${arg} requires a non-negative integer`);
      }
      if (arg === '"'-n') count = Number(value);
      else minLength = Number(value);
    } else if (arg.startsWith('-')) throw new Error("'`Unknown option: ${arg}`);
    else files.push(arg);
  }
  if (!files.length) throw new Error(usage);

  const frequencies = new Map();
  for (const file of files) {
    const text = readFileSync(file, '"'utf8').normalize('NFC');
    for (let word of text.match(/\\p{L}[\\p{L}\\p{M}]*/gu) ?? []) {
      if (ignoreCase) word = word.toLowerCase();
      if ([...word].length < minLength) continue;
      frequencies.set(word, (frequencies.get(word) ?? 0) + 1);
    }
  }
  const words = [...frequencies].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0)).slice(0, count);
  for (const [word, frequency] of words) console.log("'`${word}'"\\t"'${frequency}`);
} catch (error) {
  console.error(`wordfreq: ${error.message}`);
  process.exitCode = 1;
}
EOF
mkdir -p test
cat > test/wordfreq.test.js <<'"'EOF'
import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';

function run(t, texts, args = []) {
  const directory = mkdtempSync(join(process.cwd(), '.wordfreq-test-'));
  t.after(() => rmSync(directory, { recursive: true, force: true }));
  const files = texts.map((text, index) => {
    const file = join(directory, "'`${index}.txt`);
    writeFileSync(file, text);
    return file;
  });
  return spawnSync(process.execPath, ['"'bin/wordfreq.js', ...args, ...files], { encoding: 'utf8' });
}

test('counts across files, limits results, and sorts ties by word', t => {
  const result = run(t, ['pear apple pear', 'banana apple pear banana'], ['-n', '2']);
  assert.equal(result.status, 0);
  assert.equal(result.stdout, 'pear\\t3\\napple\\t2\\n');
});

test('applies case and length options', t => {
  const result = run(t, ['Apple apple APPLE an pear'], ['--ignore-case', '--min-length', '4']);
  assert.equal(result.status, 0);
  assert.equal(result.stdout, 'apple\\t3\\npear\\t1\\n');
});

test('rejects invalid options and missing files', t => {
  for (const args of [['-n', '-1'], ['--min-length', 'no'], ['--unknown']]) {
    assert.equal(run(t, ['apple'], args).status, 1);
  }
  assert.equal(run(t, []).status, 1);
});

test('prints nothing for empty files or a zero limit', t => {
  assert.equal(run(t, ['']).stdout, '');
  assert.equal(run(t, ['apple'], ['-n', '0']).stdout, '');
});
EOF
npm test"

/bin/zsh -lc "cat >> test/wordfreq.test.js <<'EOF'

test('splits punctuation and counts Unicode words with normalized accents', t => {
  const result = run(t, ['Café, cafe\\u0301"'! 東京。東京? naïve—naïve; 😀 123'"'], ['--ignore-case']);
  assert.equal(result.status, 0);
  assert.equal(result.stdout, 'café\\t2\\nnaïve\\t2\\n東京\\t2\\n');
});
EOF
cat >> README.md <<'EOF'

Words contain Unicode letters and combining marks. Punctuation, numbers,
emoji, and whitespace separate words. Accents use NFC normalization.
Length counts Unicode code points. Output is "'`word<TAB>count`, one word per
line. Results sort by count, then by word in code point order for ties.
Use `--` before file names that start with `-`. A count of zero prints nothing.
EOF
npm test'

